// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2011, "6-7", [{"author":"В. Черванёва","question":"Каким не может быть год?","choices":["грядущим","наступающим","текущим","уходящим","провожающим"],"key":"Д","review":["Год приходит и уходит","Грядущий или наступающий год ещё впереди, текущий идёт сейчас, уходящий кончается.","Провожают сами люди, например провожают уходящий год. «Провожающим» год обычно не называют."]},{"author":"Б. Иомдин","question":"Кто из этих персонажей наверняка назван по имени-отчеству?","choices":["Добрыня Никитич","Алёша Попович","Илья Муромец","Иван-Царевич","старик Хоттабыч"],"key":"А","review":["Имя и отчество","«Добрыня» — имя богатыря, а «Никитич» — отчество от имени Никита.","«Попович» значит сын попа, «Муромец» указывает на Муром, «Царевич» — на происхождение. «Старик» в имени Хоттабыча просто говорит о возрасте."]},{"author":"М. Тюренкова","question":"Какое из слов: золотой, серебряный, медный, стеклянный — может быть нарицательным существительным?","choices":["золотой","серебряный","медный","стеклянный","никакое"],"key":"А","review":["Обычное название монеты","Слово «золотой» может быть прилагательным: «золотой перстень».","Оно же служит существительным со значением монеты: «пять золотых». У других вариантов такого обычного самостоятельного значения нет."]},{"author":"Н. Валеева","question":"Взяться, заняться, приступить, углубиться. Что лишнее?","choices":["к работе","за работу","работой","с работы","в работу"],"key":"Г","review":["Сочетания с «работой»","Берутся за работу, занимаются работой, приступают к работе, углубляются в работу.","«С работы» можно вернуться или уйти. Ни с одним из четырёх глаголов этого списка такое сочетание не получается."]},{"author":"С. Бурлак","question":"В каком из этих слов нет приставки?","choices":["смолоть","смолить","сморить","сморозить","во всех этих словах есть приставка"],"key":"Б","review":["Приставка или корень","Смолоть связано с «молоть», сморить — с «морить», сморозить — с «морозить». У первой с- в них значение приставки.","«Смолить» значит покрывать смолой. С входит в корень смол-."]},{"author":"О. Подлесская","question":"Что нельзя закатить?","choices":["телегу","мяч","рукава","глаза","скандал"],"key":"В","review":["Что можно закатить","Телегу и мяч можно закатить куда-нибудь. Закатить глаза — повернуть их вверх, закатить скандал — устроить его.","Рукава засучивают или подкатывают. Сочетание «закатить рукава» не является обычным."]},{"author":"Л. Фёдорова","question":"Бабушка готовит обед, а внук надоедает ей своими просьбами.\n«Что ты, внучек, пристал ко мне, как … ?»\nНайдите то, что не подходит для такого сравнения.","choices":["банный лист","сонная муха","репей","собачонка","липучка"],"key":"Б","review":["Сравнение с надоедливым","«Пристал как банный лист» и «как репей» передают прилипчивость. Сравнения с липучкой и увязавшейся следом собачонкой работают так же.","Сонную муху вспоминают, когда кто-то медленный и вялый."]},{"author":"Н. Валеева","question":"Какое из данных ниже географических наименований образовано не так, как остальные?","choices":["Америка","Колумбия","Тихий океан","море Лаптевых","хребет Ломоносова"],"key":"В","review":["Откуда взялось имя места","Америка названа в честь Америго Веспуччи, Колумбия — Христофора Колумба. Море Лаптевых и хребет Ломоносова тоже носят имена людей.","«Тихий» в названии океана — характеристика, а не имя."]},{"author":"С. Переверзева","question":"Какое название падежа не содержит в себе глагол в повелительном наклонении?","choices":["родительный","винительный","творительный","предложный","все эти названия падежей содержат глагол в повелительном наклонении"],"key":"Г","review":["Спрятанное повеление","В словах «родительный», «винительный» и «творительный» есть буквенные отрезки «роди», «вини» и «твори».","Повелительное наклонение от «предложить» — «предложи». В слове «предложный» этой формы нет."]},{"author":"С. Бурлак","question":"— Я знаю англи_кий, францу_кий и неме_кий языки, — сказал старик Хоттабыч.\n— А вы, о знающие русский, заполните пропуски в этом предложении!","choices":["с, с, тс","йс, з, ц","йс, зс, ц","с, з, ц","с, зс, тц"],"key":"В","review":["Как пишутся названия языков","Прилагательные связаны со словами «Англия», «француз» и «немец».","Получаем «английский», «французский» и «немецкий». Пропущены йс, зс и ц."]},{"author":"И. Рубанов","question":"В какой из фраз (А)–(Г) слово походил употреблено неправильно?","choices":["Щенок походил на медвежонка, и его назвали Умкой.","Коля походил по комнате и успокоился.","Гроссмейстер походил пешкой на два поля вперёд.","Вася походил немного в бассейн и бросил.","Во всех фразах (А)–(Г) слово походил употреблено правильно"],"key":"В","review":["Походил или сделал ход","Щенок походил на медвежонка, человек может походить по комнате или некоторое время в бассейн.","О сделанном шахматном ходе в литературной речи говорят «гроссмейстер пошёл пешкой» или «сделал ход пешкой»."]},{"author":"А. Пиперски и А. Сомин","question":"Если взять слово Румыния и отбросить две последние буквы, получится название жителя этой страны: румын. Из названия какой страны нельзя тем же способом получить название её жителя?","choices":["Венгрия","Сербия","Словакия","Белоруссия","из всех названий (А)–(Г) можно"],"key":"Г","review":["Страна и её житель","Отбрось -ия: Венгрия → венгр, Сербия → серб, Словакия → словак.","От «Белоруссия» получится «белорусс», а название жителя пишется с одной с: «белорус»."]},{"author":"Н. Валеева","question":"Какое из этих слов можно понять как две разные глагольные формы?","choices":["дашь","съешь","ждёшь","льёшь","мстишь"],"key":"Б","review":["Приказ и будущее время","«Съешь суп!» — повелительное наклонение. «Ты съешь суп?» — форма будущего времени.","Они совпадают на письме. Для остальных глаголов формы приказа другие: «дай», «жди», «лей», «мсти»."]},{"author":"С. Бурлак и И. Иткин","question":"Даны названия пяти растений. Все эти названия можно встретить в разных изданиях, включая и биологические справочники; тем не менее одно из них возникло в результате ошибки. Какое?","choices":["василистник простой","мелколистник щетинистый","перистолистник бразильский","роголистник тёмно-зелёный","тысячелистник благородный"],"key":"А","review":["Лишняя буква в названии","Четыре названия с «листник» описывают листья растений: мелкие, перистые, похожие на рог или многочисленные.","В названии «василистник» вставили лишнее т, вероятно по аналогии с такими словами. Правильное название растения — «василисник»."]},{"author":"А. Сомин","question":"В слове м_л была пропущена одна гласная. Грише стало интересно, что это могло быть за слово. Он перебрал все возможности. Сколько слов он нашёл?","choices":["пять","шесть","семь","восемь","девять"],"key":"Г","review":["Пропущенная гласная","Получаются «мал», «мел», «мёл», «мил», «мол», «мул», «мыл» и «мял».","Здесь и названия предметов или животных, и формы глаголов, и частица «мол». Все восемь считаются."]},{"author":"Б. Иомдин","question":"В каком выражении обычно не заменяют глагол глядеть глаголом смотреть?","choices":["глядеть не на что","на ночь глядя","глядеть сквозь пальцы","глядеть правде в глаза","гляди в оба"],"key":"Б","review":["Устойчивый оборот о времени","Можно сказать «смотреть сквозь пальцы», «смотреть правде в глаза», «смотри в оба» и «смотреть не на что».","О позднем времени говорят «на ночь глядя». В этом обороте «смотря» обычно не употребляют."]},{"author":"Л. Фёдорова","question":"Какая рыба дала название одному из свойств человеческого характера?","choices":["щука","ёрш","сом","линь","акула"],"key":"Б","review":["Рыба и характер","У ерша колючие плавники. От его названия появилось прилагательное «ершистый».","Ершистым называют человека, который резко возражает и легко вступает в спор."]},{"author":"А. Пиперски","question":"Какая транскрипция лучше всего отражает естественное произношение устойчивого выражения стар и млад?","choices":["[старымлат]","[старымлад]","[стар’имлат]","[стар’имлад]","[старимлад]"],"key":"А","review":["Звуки в потоке речи","Первое слово оканчивается твёрдым [р]. Без паузы начальное и следующего слова произносится как [ы].","В конце всего оборота звонкий д оглушается до [т]. Получается [старымлат]."]},{"author":"И. Иткин","question":"«В русском языке слово не может начинаться с буквы ..., за которой идёт другая согласная буква». Как правильно заполнить пропуск в этом утверждении?","choices":["ж","ц","ч","ш","щ"],"key":"Д","review":["Две согласные в начале","После ж, ц, ч и ш согласная возможна: «ждать», «цкать», «чтить», «школа».","Среди предложенных букв именно щ обычно требует сразу после себя гласной в начале русского слова: «щука», «щётка»."]},{"author":"Т. Заболотская","question":"Какой фразеологизм является антонимичным по отношению к выражению не в своей тарелке?","choices":["как иголка в стоге сена","как рыба в воде","как в воду опущенный","как сельди в бочке","как рыба об лёд"],"key":"Б","review":["Удобно или неловко","«Не в своей тарелке» — чувствовать себя неуютно, неловко.","«Как рыба в воде» говорят о том, кто в привычной обстановке держится естественно и уверенно."]},{"author":"Л. Фёдорова","question":"Для какого примера невозможно слитное написание:\n1) (во)все, 2) (со)всем, 3) (на)весь, 4) (во)всю?","choices":["только для 1","только для 2","только для 3","только для 4","для всех примеров возможно как раздельное, так и слитное написание"],"key":"Д","review":["Вместе и раздельно","«Вовсе забыл» — «во все стороны»; «совсем готов» — «со всем классом».","«Навесь дверь» — «на весь экран»; «вовсю работает» — «во всю ширину». Для всех четырёх пар возможны оба написания."]},{"author":"И. Иткин","question":"Рост, дух, прыть, горло... Каким словом можно продолжить этот список?","choices":["блюдце","голос","колос","подсвечник","скорость"],"key":"Б","review":["Сочетание с «во весь»","Есть обороты «во весь рост», «во весь дух», «во всю прыть» и «во всё горло».","«Кричать во весь голос» построено по той же модели."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Вы стали похож_ на сестру. Как нельзя заполнить пропуск?","choices":["и","ими","им","ей","пропуск можно заполнить любым из способов, предложенных в (А)–(Г)"],"key":"Д","review":["Согласование со словом «вы»","«Вы стали похожи» и «похожими» грамматически согласуются с обращением к нескольким людям.","При вежливом обращении к одному допустимы «похожим» о мужчине и «похожей» о женщине."]},{"author":"Е. Муравенко","question":"В русском языке многие неопределённые формы глаголов (инфинитивы) устроены так, что если их написать без мягкого знака, то получится форма ед. или мн.ч. 3-го лица того же глагола. В каком случае, убрав мягкий знак, мы получим форму другого глагола?","choices":["садиться","вернуться","наесться","бояться","решаться"],"key":"Д","review":["Инфинитив и другая основа","«Садится», «вернутся», «наестся» и «боятся» относятся к тем же глаголам, что соответствующие инфинитивы в условии.","От «решаться» образуется «решается» или «решаются». Без ь получилось «решатся» — форма глагола «решиться»."]},{"author":"А. Сомин","question":"Джон изучает русский язык. Однажды преподаватель дал ему список музыкальных инструментов: арфа, балалайка, барабан, гусли, саксофон, скрипка, труба — и попросил найти в словаре все слова, которыми можно назвать музыкантов-мужчин, играющих на этих инструментах. Джон верно выполнил задание. Сколько разных суффиксов оказалось в выписанных им словах?","choices":["два","три","четыре","пять","шесть"],"key":"Г","review":["Названия музыкантов","Арфист и саксофонист имеют суффикс -ист, скрипач и трубач — -ач.","Остальные названия — балалаечник, барабанщик и гусляр — дают -ник, -щик и -яр. Всего пять разных суффиксов."]},{"author":"А. Пиперски","question":"Я был ра…троган до слёз ра…казом про то, как семья белых медведей искала себе новое жильё, потому что их любимая льдина ра…таяла. Что надо поставить вместо многоточий?","choices":["сс, с, сс","с, сс, с","с, сс, сс","сс, сс, с","сс, сс, сс"],"key":"Б","review":["Граница приставки и корня","Во всех случаях приставка рас- оканчивается на с перед глухой согласной: трог-, сказ- и та-.","Две с получаются только в «рассказе», где одна с относится к приставке, а вторая к корню. Ответ: с, сс, с."]},{"author":"А. Пиперски","question":"Даны три фразы с пропусками:\n1) Мама, перебирая бельё, насчитала … чулок и вздохнула: «Опять что-то потерялось!»\n2) … человек пришло на открытие выставки мебели.\n3) На дереве сидит … ворона.\nПодставляя на место многоточий числа 21, 23, 29, получаем девять фраз. Сколько среди них правильных?","choices":["три","четыре","пять","шесть","семь"],"key":"В","review":["Числительные и формы слов","«Двадцать один чулок» и «двадцать девять чулок» верны, а «двадцать три» требует «чулка».","«Пришло» здесь сочетается с 23 и 29 людьми, при 21 нужно «пришёл». С «ворона» подходит только 21 — ещё один пример. Всего пять."]},{"author":"Б. Иомдин","question":"В одной газете читаем: «Девяносто два года — возраст солидный. Но, глядя на Мухтара Юсуповича Юсупова, ни за что не скажешь, что он разменял сотый десяток. Держится просто молодцом, на лице улыбка». А как надо было написать?","choices":["разменял девяностый десяток","разменял девятый десяток","разменял десятый десяток","разменял девять десятков","разменял десять десятков"],"key":"В","review":["Какой десяток теперь идёт","В 90 лет исполняется девять десятков. Числа от 91 до 100 входят в следующий, десятый десяток.","О человеке 92 лет говорят, что он разменял десятый десяток."]},{"author":"А. Пиперски","question":"Даны несколько отдельных строк из стихотворения В. Я. Брюсова «Пророчество мечты», написанных так называемым ропалическим стихом:\n1) Жизнь предать согласен сновиденью бесконечному.\n2) Ах, тая проклятья, истинные, освященные!\n3) И, губя, приветит лепетами полуясными…\nКакая пара слов не может встретиться в пределах одной строки ропалического стиха?","choices":["горестными и рыдает","доверясь и опять","настанет и отметит","невозможное и совершится","обманет и повторится"],"key":"В","review":["Слоги по порядку","Слова в каждой строке имеют по одному, два, три, четыре и пять слогов. Двух слов одной длины в строке нет.","В «настанет» и «отметит» по три слога. Эти слова претендуют на одно место в строке."]},{"author":"П. Аркадьев","question":"Даны существительные языка лорабада* в единственном и во множественном числе:\nahara — aharafe ‘брат’\naru — aruvoro ‘мужчина’\nlaira — lairafe ‘тётя’\nmini — minivoro ‘птица’\nevera — everavoro ‘собака’\nКак выглядят формы множественного числа следующих существительных языка лорабада: aiparo ‘свинья’, onera ‘сестра’, napara ‘отец’?\n* Язык лорабада — один из папуасских языков. На нём говорит около 500 человек на юго-восточном побережье острова Новая Гвинея.","choices":["aiparofe, onerafe, naparafe","aiparovoro, onerafe, naparafe","aiparovoro, oneravoro, naparafe","aiparofe, oneravoro, naparavoro","aiparovoro, onerafe, naparavoro"],"key":"Б","review":["Два показателя числа","Термины родства «брат» и «тётя» принимают -fe. У «мужчины», «птицы» и «собаки» показатель -voro.","Сестра и отец — родственники: onerafe и naparafe. Свинья относится к животным: aiparovoro."]}], {"year":2011,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2011.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
